use std::{fs,path::PathBuf,sync::{Mutex,Arc,atomic::{AtomicBool,Ordering}},time::{Duration,SystemTime,UNIX_EPOCH}};
use serde::Serialize;
use tauri::{AppHandle,State,Manager};
use tauri_plugin_dialog::DialogExt;
use tauri_plugin_opener::OpenerExt;
use crate::{assistant_core::*,application_registry::{Entry,Target}};
#[derive(Default)]pub struct Assistant(pub Mutex<Data>);
#[derive(Default)]pub struct Data{pending:Option<String>,search:Option<Arc<AtomicBool>>,results:Vec<FolderMatch>,generation:u64}
#[derive(Serialize)]pub struct StepResult{pub name:String,pub ok:bool,pub detail:String}
#[derive(Serialize)]pub struct ShortcutResult{pub status:String,pub id:String,pub name:String,pub target:String,pub results:Vec<StepResult>}
#[derive(Serialize)]#[serde(rename_all="camelCase")]pub struct FolderResponse{#[serde(flatten)]pub search:SearchResult,pub opened:Option<PathBuf>}
fn config(app:&AppHandle)->Result<PathBuf,String>{Ok(app.path().app_config_dir().map_err(|_|"No se encontró la configuración.")?.join("shortcuts-v1.json"))}
fn read(app:&AppHandle)->Result<Vec<Shortcut>,String>{let p=config(app)?;crate::config_migration::migrate_file(&p,1024*1024,"shortcuts").map_err(|e|format!("No se pudo migrar la configuración de atajos: {e}"))}
fn save(app:&AppHandle,items:&[Shortcut])->Result<(),String>{let entries=crate::applications::configured(app)?;let names:Vec<_>=entries.iter().flat_map(|e|std::iter::once(e.name.clone()).chain(e.aliases.clone())).collect();validate_shortcuts(items,&names)?;for s in items{for a in &s.actions{match a{Action::App{app_id,profile_directory}=>{let entry=app_entry(&entries,app_id)?;if let Some(profile)=profile_directory{chrome_profile(app,entry,profile)?;}},Action::Url{url,browser_id,profile_directory}=>{web_url(url)?;if let Some(id)=browser_id{browser(&entries,id)?;if let Some(profile)=profile_directory{chrome_profile(app,app_entry(&entries,id)?,profile)?;}}},_=>{}}}}write_shortcuts(app,items)}
fn write_shortcuts(app:&AppHandle,items:&[Shortcut])->Result<(),String>{let path=config(app)?;let bytes=crate::config_migration::encode_items(items,"shortcuts")?;crate::config_migration::write_atomic(&path,&bytes)}
fn app_entry<'a>(entries:&'a[Entry],id:&str)->Result<&'a Entry,String>{entries.iter().find(|e|e.id==id).ok_or_else(||"Una aplicación del atajo ya no está registrada.".into())}
fn browser<'a>(entries:&'a[Entry],id:&str)->Result<&'a PathBuf,String>{let e=app_entry(entries,id)?;match &e.target{Target::Exe{path}=>{let name=path.file_name().unwrap_or_default().to_string_lossy().to_lowercase();if matches!(name.as_str(),"chrome.exe"|"msedge.exe"|"firefox.exe"|"brave.exe"|"opera.exe"|"vivaldi.exe"){Ok(path)}else{Err("Elegí un navegador compatible para abrir la página.".into())}},_=>Err("Elegí un navegador para la página.".into())}}
fn web_url(value:&str)->Result<reqwest::Url,String>{if !valid_web_url(value){return Err("La página debe comenzar con http:// o https://.".into())}let url=reqwest::Url::parse(value).map_err(|_|"La dirección de la página es inválida.")?;if url.host_str().is_none()||!url.username().is_empty()||url.password().is_some(){return Err("La página debe tener un dominio y no incluir credenciales.".into())}Ok(url)}
pub(crate) fn local_folder(path:&std::path::Path)->Result<PathBuf,String>{let p=path.canonicalize().map_err(|_|"La carpeta ya no existe o no está disponible.")?;if !p.is_dir(){return Err("El destino ya no es una carpeta.".into())}if !local_path(&p){return Err("Elegí una carpeta de un disco local.".into())}Ok(shell_folder_path(p))}
fn execute(app:&AppHandle,s:&Shortcut)->Result<ShortcutResult,String>{let entries=crate::applications::configured(app)?;if s.actions.is_empty()||s.actions.len()>12{return Err("El atajo debe tener entre 1 y 12 acciones.".into())}let results=s.actions.iter().map(|a|{let (name,result)=match a{
 Action::App{app_id,profile_directory}=>match app_entry(&entries,app_id){Ok(e)=>(e.name.clone(),if let Some(profile)=profile_directory{launch_chrome_profile(app,e,profile,None)}else{crate::applications::launch(app,e)}),Err(e)=>(app_id.clone(),Err(e))},
 Action::Url{url,browser_id,profile_directory}=>(url.clone(),(||{let url=web_url(url)?;if let Some(id)=browser_id{if let Some(profile)=profile_directory{launch_chrome_profile(app,app_entry(&entries,id)?,profile,Some(url.as_str()))}else{std::process::Command::new(browser(&entries,id)?).arg(url.as_str()).spawn().map(|_|()).map_err(|e|e.to_string())}}else{app.opener().open_url(url.as_str(),None::<&str>).map_err(|e|e.to_string())}})()),
 Action::Folder{path}=>(path.display().to_string(),local_folder(path).and_then(|p|app.opener().open_path(p.to_string_lossy().into_owned(),None::<&str>).map_err(|e|e.to_string())))
 };StepResult{name,ok:result.is_ok(),detail:result.err().unwrap_or_else(||"Apertura solicitada a Windows.".into())}}).collect();Ok(ShortcutResult{status:"opened".into(),id:s.id.clone(),name:s.name.clone(),target:format!("{} acciones",s.actions.len()),results})}
#[tauri::command]pub fn shortcuts_list(app:AppHandle)->Result<Vec<Shortcut>,String>{read(&app)}
// A click on a configured mode explicitly requests execution. Voice and chat
// continue to use the existing confirmation and remembered-permission flow.
#[tauri::command]pub async fn shortcuts_run_button(id:String,app:AppHandle,state:State<'_,Assistant>)->Result<ShortcutResult,String>{
 {let data=state.inner().0.lock().map_err(|_|"Atajos ocupados.")?;if data.pending.is_some(){return Err("Confirmá o cancelá el atajo pendiente.".into())}}
 tauri::async_runtime::spawn_blocking(move||{
  let shortcut=read(&app)?.into_iter().find(|s|s.id==id).ok_or("Este atajo ya no existe. Volvé a configurar tus modos.")?;
  execute(&app,&shortcut)
 }).await.map_err(|e|e.to_string())?
}
#[tauri::command]pub fn shortcuts_save(mut shortcut:Shortcut,app:AppHandle,state:State<'_,Assistant>)->Result<Vec<Shortcut>,String>{let mut data=state.inner().0.lock().map_err(|_|"Atajos ocupados.")?;if data.pending.is_some(){return Err("Confirmá o cancelá el atajo pendiente.".into())}let mut items=read(&app)?;shortcut.name=shortcut.name.trim().into();shortcut.aliases=shortcut.aliases.into_iter().map(|a|a.trim().to_string()).filter(|a|!a.is_empty()).collect();if shortcut.id.is_empty(){shortcut.id=format!("shortcut-{}",SystemTime::now().duration_since(UNIX_EPOCH).map_err(|e|e.to_string())?.as_nanos());items.push(shortcut)}else{let old=items.iter_mut().find(|s|s.id==shortcut.id).ok_or("Ese atajo ya no existe.")?;*old=shortcut;}save(&app,&items)?;data.pending=None;Ok(items)}
#[tauri::command]pub fn shortcuts_reorder(ids:Vec<String>,app:AppHandle,state:State<'_,Assistant>)->Result<Vec<Shortcut>,String>{let data=state.inner().0.lock().map_err(|_|"Atajos ocupados.")?;if data.pending.is_some(){return Err("Hay un atajo pendiente.".into())}let items=reorder_shortcuts(read(&app)?,&ids)?;write_shortcuts(&app,&items)?;Ok(items)}
#[tauri::command]pub fn shortcuts_remove(id:String,app:AppHandle,state:State<'_,Assistant>)->Result<Vec<Shortcut>,String>{let data=state.inner().0.lock().map_err(|_|"Atajos ocupados.")?;if data.pending.is_some(){return Err("Hay un atajo pendiente.".into())};let mut items=read(&app)?;items.retain(|s|s.id!=id);save(&app,&items)?;Ok(items)}
#[tauri::command]pub fn shortcuts_request(text:String,app:AppHandle,state:State<'_,Assistant>)->Result<Option<ShortcutResult>,String>{let mut data=state.inner().0.lock().map_err(|_|"Atajos ocupados.")?;if data.pending.is_some(){return Err("Confirmá el atajo pendiente.".into())}let Some(s)=read(&app)?.into_iter().find(|s|shortcut_matches(s,&text))else{return Ok(None)};if s.remember{return execute(&app,&s).map(Some)}let target=s.actions.iter().map(|a|match a{Action::App{app_id,..}=>crate::applications::configured(&app).ok().and_then(|e|e.into_iter().find(|e|e.id==*app_id)).map(|e|e.name).unwrap_or_else(||app_id.clone()),Action::Url{url,..}=>url.clone(),Action::Folder{path}=>path.display().to_string()}).collect::<Vec<_>>().join(" → ");data.pending=Some(s.id.clone());Ok(Some(ShortcutResult{status:"confirm".into(),id:s.id,name:s.name,target,results:vec![]}))}
#[tauri::command]pub fn shortcuts_confirm(id:String,remember:bool,app:AppHandle,state:State<'_,Assistant>)->Result<ShortcutResult,String>{let mut data=state.inner().0.lock().map_err(|_|"Atajos ocupados.")?;if data.pending.as_deref()!=Some(&id){return Err("La solicitud de atajo cambió.".into())}data.pending=None;let mut items=read(&app)?;let index=items.iter().position(|s|s.id==id).ok_or("El atajo ya no existe.")?;if remember{items[index].remember=true;save(&app,&items)?}execute(&app,&items[index])}
#[tauri::command]pub fn shortcuts_cancel(state:State<'_,Assistant>)->Result<(),String>{state.inner().0.lock().map_err(|_|"Atajos ocupados.")?.pending=None;Ok(())}
#[tauri::command]pub async fn assistant_pick_folder(app:AppHandle)->Result<Option<PathBuf>,String>{tauri::async_runtime::spawn_blocking(move||{let d=app.dialog().file().set_title("Elegir una carpeta local");let d=if let Some(w)=app.get_webview_window("main"){d.set_parent(&w)}else{d};d.blocking_pick_folder().map(|p|p.into_path().map_err(|_|"Ruta inválida.".to_string()).and_then(|p|local_folder(&p))).transpose()}).await.map_err(|e|e.to_string())?}
#[cfg(windows)]pub(crate) fn roots()->Vec<PathBuf>{let mut result=vec![];if let Some(profile)=std::env::var_os("USERPROFILE"){let p=PathBuf::from(profile);for sub in ["Desktop","Documents","Pictures","Downloads","OneDrive"]{let d=p.join(sub);if d.is_dir(){result.push(d)}}result.push(p)}for c in b'C'..=b'Z'{let drive=format!("{}:\\",c as char);let wide:Vec<u16>=drive.encode_utf16().chain(Some(0)).collect();let kind=unsafe{windows_sys::Win32::Storage::FileSystem::GetDriveTypeW(wide.as_ptr())};if kind==2||kind==3{result.push(PathBuf::from(drive))}}result}
#[cfg(not(windows))]pub(crate) fn roots()->Vec<PathBuf>{std::env::var_os("HOME").map(PathBuf::from).into_iter().collect()}
#[tauri::command]pub async fn folders_search(text:String,within:Option<PathBuf>,app:AppHandle,state:State<'_,Assistant>)->Result<FolderResponse,String>{let request=folder_request(&text).ok_or("Probá: buscá una carpeta llamada fotos de viajes y abrila.")?;let roots=if let Some(p)=within{vec![local_folder(&p)?]}else{roots()};let cancel=Arc::new(AtomicBool::new(false));let generation={let mut d=state.inner().0.lock().map_err(|_|"Búsqueda ocupada.")?;if let Some(old)=d.search.take(){old.store(true,Ordering::Relaxed)}d.generation+=1;d.results.clear();d.search=Some(cancel.clone());d.generation};let q=request.name.clone();let token=cancel.clone();let mut search=tauri::async_runtime::spawn_blocking(move||search_folders(roots,&q,&token,Duration::from_secs(15),300000)).await.map_err(|e|e.to_string())?;let mut d=state.inner().0.lock().map_err(|_|"Búsqueda ocupada.")?;if d.generation!=generation||cancel.load(Ordering::Relaxed){search.cancelled=true;search.matches.clear();return Ok(FolderResponse{search,opened:None})}d.search=None;for(i,m)in search.matches.iter_mut().enumerate(){m.id=format!("folder-{generation}-{i}")}d.results=search.matches.clone();let mut opened=None;if request.open&&!search.incomplete&&search.matches.len()==1&&search.matches[0].exact{let p=local_folder(&search.matches[0].path)?;app.opener().open_path(p.to_string_lossy().into_owned(),None::<&str>).map_err(|e|e.to_string())?;opened=Some(p)}Ok(FolderResponse{search,opened})}
#[tauri::command]pub fn folders_open(id:String,app:AppHandle,state:State<'_,Assistant>)->Result<PathBuf,String>{let d=state.inner().0.lock().map_err(|_|"Búsqueda ocupada.")?;let m=d.results.iter().find(|m|m.id==id).ok_or("La búsqueda cambió. Volvé a buscar la carpeta.")?;let p=local_folder(&m.path)?;app.opener().open_path(p.to_string_lossy().into_owned(),None::<&str>).map_err(|e|e.to_string())?;Ok(p)}
#[tauri::command]pub fn folders_cancel(state:State<'_,Assistant>)->Result<(),String>{let mut d=state.inner().0.lock().map_err(|_|"Búsqueda ocupada.")?;d.generation+=1;if let Some(token)=d.search.take(){token.store(true,Ordering::Relaxed)}d.results.clear();Ok(())}

pub(crate) fn names(app:&AppHandle)->Result<Vec<String>,String>{Ok(read(app)?.into_iter().flat_map(|s|std::iter::once(s.name).chain(s.aliases)).collect())}

fn chrome_exe(entry:&Entry)->Result<&PathBuf,String>{match &entry.target{Target::Exe{path} if path.file_name().is_some_and(|s|s.to_string_lossy().eq_ignore_ascii_case("chrome.exe"))=>Ok(path),_=>Err("La selección de perfil está disponible para Google Chrome.".into())}}
fn chrome_data()->Result<PathBuf,String>{std::env::var_os("LOCALAPPDATA").map(|p|PathBuf::from(p).join("Google/Chrome/User Data")).ok_or_else(||"No se encontró la carpeta de perfiles de Chrome.".into())}
fn profiles(entry:&Entry)->Result<Vec<ChromeProfile>,String>{chrome_exe(entry)?;let root=chrome_data()?;let path=root.join("Local State");let meta=fs::metadata(&path).map_err(|_|"Abrí Chrome con el perfil deseado y volvé a detectar los perfiles.".to_string())?;if meta.len()>8*1024*1024{return Err("La configuración de Chrome es demasiado grande.".into())}let bytes=fs::read(path).map_err(|_|"No se pudieron leer los perfiles de Chrome.")?;Ok(parse_chrome_profiles(&bytes)?.into_iter().filter(|p|root.join(&p.id).is_dir()).collect())}
fn chrome_profile(_app:&AppHandle,entry:&Entry,id:&str)->Result<(),String>{if !valid_profile_id(id)||!profiles(entry)?.iter().any(|p|p.id==id){return Err("El perfil de Chrome ya no está disponible. Volvé a detectarlo en el atajo.".into())}Ok(())}
fn launch_chrome_profile(app:&AppHandle,entry:&Entry,id:&str,url:Option<&str>)->Result<(),String>{chrome_profile(app,entry,id)?;let mut command=std::process::Command::new(chrome_exe(entry)?);command.arg(format!("--profile-directory={id}")).arg("--ignore-profile-directory-if-not-exists");if let Some(url)=url{command.arg(url);}command.spawn().map(|_|()).map_err(|e|format!("No se pudo abrir Chrome con ese perfil: {e}"))}
#[tauri::command]pub fn chrome_profiles(app_id:String,app:AppHandle)->Result<Vec<ChromeProfile>,String>{let entries=crate::applications::configured(&app)?;profiles(app_entry(&entries,&app_id)?)}
